// McpGatewayServiceHandler is an implementation of the chalk.mcp_gateway.v1.McpGatewayService
// service.
type McpGatewayServiceHandler interface {
	GetMe(context.Context, *connect.Request[v1.GetMeRequest]) (*connect.Response[v1.GetMeResponse], error)
	ListBackends(context.Context, *connect.Request[v1.ListBackendsRequest]) (*connect.Response[v1.ListBackendsResponse], error)
	GetBackend(context.Context, *connect.Request[v1.GetBackendRequest]) (*connect.Response[v1.GetBackendResponse], error)
	CallTool(context.Context, *connect.Request[v1.CallToolRequest]) (*connect.Response[v1.CallToolResponse], error)
	ReadResource(context.Context, *connect.Request[v1.ReadResourceRequest]) (*connect.Response[v1.ReadResourceResponse], error)
	GetPrompt(context.Context, *connect.Request[v1.GetPromptRequest]) (*connect.Response[v1.GetPromptResponse], error)
	ListAgents(context.Context, *connect.Request[v1.ListAgentsRequest]) (*connect.Response[v1.ListAgentsResponse], error)
	GetAgent(context.Context, *connect.Request[v1.GetAgentRequest]) (*connect.Response[v1.GetAgentResponse], error)
	SetAgent(context.Context, *connect.Request[v1.SetAgentRequest]) (*connect.Response[v1.SetAgentResponse], error)
	DeleteAgent(context.Context, *connect.Request[v1.DeleteAgentRequest]) (*connect.Response[v1.DeleteAgentResponse], error)
	ListToolBelts(context.Context, *connect.Request[v1.ListToolBeltsRequest]) (*connect.Response[v1.ListToolBeltsResponse], error)
	GetToolBelt(context.Context, *connect.Request[v1.GetToolBeltRequest]) (*connect.Response[v1.GetToolBeltResponse], error)
	// Belts reshape the endpoint every caller of that belt connects to, so
	// changing one takes team admin even though the gateway itself does not ask.
	SetToolBelt(context.Context, *connect.Request[v1.SetToolBeltRequest]) (*connect.Response[v1.SetToolBeltResponse], error)
	DeleteToolBelt(context.Context, *connect.Request[v1.DeleteToolBeltRequest]) (*connect.Response[v1.DeleteToolBeltResponse], error)
	ListOauthLinks(context.Context, *connect.Request[v1.ListOauthLinksRequest]) (*connect.Response[v1.ListOauthLinksResponse], error)
	UnlinkOauth(context.Context, *connect.Request[v1.UnlinkOauthRequest]) (*connect.Response[v1.UnlinkOauthResponse], error)
	// Every user's OAuth links in the environment; tokens are never returned.
	ListOauthBindings(context.Context, *connect.Request[v1.ListOauthBindingsRequest]) (*connect.Response[v1.ListOauthBindingsResponse], error)
	ListServers(context.Context, *connect.Request[v1.ListServersRequest]) (*connect.Response[v1.ListServersResponse], error)
	GetServer(context.Context, *connect.Request[v1.GetServerRequest]) (*connect.Response[v1.GetServerResponse], error)
	CreateServer(context.Context, *connect.Request[v1.CreateServerRequest]) (*connect.Response[v1.CreateServerResponse], error)
	UpdateServer(context.Context, *connect.Request[v1.UpdateServerRequest]) (*connect.Response[v1.UpdateServerResponse], error)
	DeleteServer(context.Context, *connect.Request[v1.DeleteServerRequest]) (*connect.Response[v1.DeleteServerResponse], error)
	// Compiles a spec into the tools an `openapi` backend would expose; writes
	// nothing and does not provision a gateway.
	PreviewOpenapi(context.Context, *connect.Request[v1.PreviewOpenapiRequest]) (*connect.Response[v1.PreviewOpenapiResponse], error)
	SimulatePolicy(context.Context, *connect.Request[v1.SimulatePolicyRequest]) (*connect.Response[v1.SimulatePolicyResponse], error)
	CheckPolicy(context.Context, *connect.Request[v1.CheckPolicyRequest]) (*connect.Response[v1.CheckPolicyResponse], error)
	RecentAudit(context.Context, *connect.Request[v1.RecentAuditRequest]) (*connect.Response[v1.RecentAuditResponse], error)
	// Removed: always fails with UNIMPLEMENTED. It only pushed events recorded
	// by the replica the stream landed on. Poll RecentAudit with `after`
	// instead. The definition stays so the schema remains wire compatible.
	//
	// Deprecated: do not use.
	StreamAudit(context.Context, *connect.Request[v1.StreamAuditRequest], *connect.ServerStream[v1.StreamAuditResponse]) error
	ListPolicies(context.Context, *connect.Request[v1.ListPoliciesRequest]) (*connect.Response[v1.ListPoliciesResponse], error)
	GetPolicy(context.Context, *connect.Request[v1.GetPolicyRequest]) (*connect.Response[v1.GetPolicyResponse], error)
	SetPolicy(context.Context, *connect.Request[v1.SetPolicyRequest]) (*connect.Response[v1.SetPolicyResponse], error)
	DeletePolicy(context.Context, *connect.Request[v1.DeletePolicyRequest]) (*connect.Response[v1.DeletePolicyResponse], error)
	ListTrustedIssuers(context.Context, *connect.Request[v1.ListTrustedIssuersRequest]) (*connect.Response[v1.ListTrustedIssuersResponse], error)
	GetTrustedIssuer(context.Context, *connect.Request[v1.GetTrustedIssuerRequest]) (*connect.Response[v1.GetTrustedIssuerResponse], error)
	// A trusted issuer lets tokens from an outside OIDC provider authenticate
	// to the gateway as agents, so adding, changing or removing one takes team
	// admin, like the other environment-wide gateway settings.
	SetTrustedIssuer(context.Context, *connect.Request[v1.SetTrustedIssuerRequest]) (*connect.Response[v1.SetTrustedIssuerResponse], error)
	DeleteTrustedIssuer(context.Context, *connect.Request[v1.DeleteTrustedIssuerRequest]) (*connect.Response[v1.DeleteTrustedIssuerResponse], error)
	// Evaluates a mapping against sample claims; stores nothing.
	PreviewClaimsMapping(context.Context, *connect.Request[v1.PreviewClaimsMappingRequest]) (*connect.Response[v1.PreviewClaimsMappingResponse], error)
}

